set-variable.value:
@{
    try {
      var stores = Newtonsoft.Json.Linq.JArray.Parse((string)context.Variables["byokResponseStores"]);
      if (stores.Count == 0 || stores.Count > 8) { return false; }
      var identifiers = new System.Collections.Generic.HashSet<string>(StringComparer.OrdinalIgnoreCase);
      var origins = new System.Collections.Generic.HashSet<string>(StringComparer.OrdinalIgnoreCase);
      foreach (var entry in stores) {
        if (entry.Type != Newtonsoft.Json.Linq.JTokenType.Object || entry["origin"]?.Type != Newtonsoft.Json.Linq.JTokenType.String
            || entry["backendId"]?.Type != Newtonsoft.Json.Linq.JTokenType.String || entry["kind"]?.Type != Newtonsoft.Json.Linq.JTokenType.String
            || !System.Text.RegularExpressions.Regex.IsMatch((string)entry["backendId"], @"\A[A-Za-z0-9_-]{1,80}\z")
            || !new[] { "foundry", "aoai", "commercial" }.Contains((string)entry["kind"])) { return false; }
          var origin = new Uri((string)entry["origin"]);
          if (origin.Scheme != "https" || origin.Port != 443
            || origin.IsLoopback || origin.Host.EndsWith(".invalid", StringComparison.OrdinalIgnoreCase)
            || !string.IsNullOrEmpty(origin.UserInfo) || !string.IsNullOrEmpty(origin.Query) || !string.IsNullOrEmpty(origin.Fragment)
            || origin.AbsolutePath != "/" || !identifiers.Add((string)entry["backendId"])
            || !origins.Add(origin.Scheme + "://" + origin.Authority)) { return false; }
      }
      return true;
    } catch { return false; }
  }
